// Checks the driver against reference frames (reference-vectors.json, generated by running a
// reference Python implementation with its I/O stubbed out).
import { describe, expect, it } from 'vitest'
import vectors from './reference-vectors.json'
import { HottopDriver, type SetHottopArgs } from './driver'
import { FrameParser, decodeStatus, encodeCommand, roundHalfEven } from './protocol'
import type { Transport, TransportHandlers } from './transport'

type PyArgs = Partial<
  Record<'heater' | 'fan' | 'main_fan', number> & Record<'solenoid' | 'drum_motor' | 'cooling_motor', boolean>
>

function toArgs(a: PyArgs): SetHottopArgs {
  return {
    heater: a.heater,
    fan: a.fan,
    mainFan: a.main_fan,
    solenoid: a.solenoid,
    drumMotor: a.drum_motor,
    coolingMotor: a.cooling_motor,
  }
}

class FakeTransport implements Transport {
  label = 'fake'
  handlers!: TransportHandlers
  written: Uint8Array[] = []
  async open(h: TransportHandlers) {
    this.handlers = h
  }
  async write(b: Uint8Array) {
    this.written.push(b)
  }
  async close() {}
}

describe('matches the reference vectors', () => {
  const encodes = vectors.filter((v) => v.kind === 'encode')
  const echoes = vectors.filter((v) => v.kind === 'echo')

  it('has vectors', () => {
    expect(encodes.length).toBeGreaterThan(100)
    expect(echoes.length).toBeGreaterThan(100)
  })

  it('setHottop + create_msg produce identical bytes', () => {
    for (const v of encodes) {
      const d = new HottopDriver()
      d.setHottop(toArgs(v.args as PyArgs))
      expect(Array.from(encodeCommand(d.getSnapshot().commanded))).toEqual(v.bytes)
    }
  })

  it('decodes status frames and answers them like read_msg (except the cooling-fan fix)', async () => {
    for (const v of echoes) {
      const t = new FakeTransport()
      const d = new HottopDriver()
      await d.connect(t)
      d.setHottop(toArgs(v.args as PyArgs))
      t.handlers.onData(Uint8Array.from(v.status as number[]))

      const r = d.getSnapshot().readings
      const [bt, et, heater, mainFan, fanRaw, solenoid, drum, cooling] = v.state as number[]
      expect([r.bt, r.et, r.heater, r.mainFan, r.solenoid, r.drumMotor, r.coolingMotor]).toEqual([
        bt,
        et,
        heater,
        mainFan,
        solenoid,
        drum,
        cooling,
      ])
      expect(r.fan).toBe(fanRaw * 10) // the reference keeps byte 11 raw (0–10); we scale it to %

      expect(t.written).toHaveLength(1)
      const ours = Array.from(t.written[0])
      const theirs = v.reply as number[]
      const cutoff = bt >= 220
      for (let i = 0; i < 35; i++) {
        if (i === 11) continue
        if (i === 12 && cutoff) continue
        expect(ours[i], `byte ${i}`).toBe(theirs[i])
      }
      // Safety cutoff: the reference sets the main fan to 10 on its 0–100 scale, which goes out as
      // 1 of 10. The comment and the rest of the cut (heater off, door open) say "max", so we send 10.
      if (cutoff) {
        expect(theirs[12]).toBe(1)
        expect(ours[12]).toBe(10)
      }
      // Byte 11: the reference echoes round(raw/10) — a bug — we echo the machine's actual value.
      if (!('fan' in v.args)) {
        expect(theirs[11]).toBe(roundHalfEven(fanRaw / 10))
        expect(ours[11]).toBe(fanRaw)
      }
    }
  })
})

describe('protocol details', () => {
  it('rounds half to even like Python', () => {
    expect([0.5, 1.5, 2.5, 3.5, 2.4, 2.6].map(roundHalfEven)).toEqual([0, 2, 2, 4, 2, 3])
  })

  it('resyncs across junk and split chunks', () => {
    const frame = encodeCommand({ heater: 50, fan: 30, mainFan: 70, solenoid: 0, drumMotor: 1, coolingMotor: 0 })
    const stream = new Uint8Array([0x01, 0xa5, 0x00, 0x33, ...frame, ...frame])
    const p = new FrameParser()
    const got = [...p.push(stream.slice(0, 20)), ...p.push(stream.slice(20))]
    expect(got).toHaveLength(2)
    expect(decodeStatus(got[0]).heater).toBe(50)
  })

  it('controls from the first frame, echoing the machine, and cuts off at 220 °C', async () => {
    const t = new FakeTransport()
    const d = new HottopDriver()
    await d.connect(t)
    const status = (bt: number) => {
      const f = new Uint8Array(36)
      f[0] = 0xa5
      f[1] = 0x96
      f[10] = 40 // heater
      f[12] = 6 // main fan
      f[25] = bt >> 8
      f[26] = bt & 0xff
      f[35] = f.slice(0, 35).reduce((a, b) => a + b, 0) & 0xff
      return f
    }
    t.handlers.onData(status(150))
    expect(t.written).toHaveLength(1)
    expect([t.written[0][10], t.written[0][12]]).toEqual([40, 6]) // untouched outputs echo the machine
    expect(d.getSnapshot().cutoffActive).toBe(false)

    t.handlers.onData(status(220))
    expect(d.getSnapshot().cutoffActive).toBe(true)
    expect([t.written[1][10], t.written[1][12]]).toEqual([0, 10])
  })
})
